definition.script:
pipeline {
  agent any

  tools {
    nodejs 'node25'
  }

  options {
    timestamps()
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Install') {
      steps {
        sh '''
          npm config set @esbuild-kit:registry https://registry.npmjs.org/ --location=project
          npm install --no-audit --no-fund
        '''
      }
    }

    stage('Validate') {
      steps {
        sh '''
          npm run lint --if-present
          npm run typecheck --if-present
          npm test --if-present
          npm run build --if-present
        '''
      }
    }
  }
}
